const player = {
  name: "Ranger",
  xp: 450,
  level: function() {
    return Math.floor(this.xp / 100);
  },
  canEnter: function(minLevel) {
    if (this.level() >= minLevel) {
      return true;
    } else {
      return false;
    }
  }
};
console.log(player.canEnter(5));

